void JAInter::SeMgr::sendSeAllParameter(JAISound* i_sound) {
    SeqUpdateData* trackInfo;
    SeParameter* para;
    seTrackUpdate_s* trackUpdate = &seTrackUpdate[i_sound->getPlayTrackNo()];
    para = i_sound->getSeParameter();
    trackInfo = SequenceMgr::getPlayTrackInfo(seHandle->getPlayTrackNo());
    checkPlayingSeUpdateMultiplication(
        i_sound,
        trackInfo,
        para->field_0x424,
        para->mVolumes,
        seCategoryVolume[i_sound->getSeCategoryNumber()],
        2,
        &trackUpdate->mPlayingVolume
    );
    checkPlayingSeUpdateAddition(i_sound, trackInfo, para->field_0x428, para->mPans, 4, &trackUpdate->mPlayingPan, 0.5f);
    checkPlayingSeUpdateMultiplication(i_sound, trackInfo, para->field_0x42c, para->mPitches, 1.0f, 3, &trackUpdate->mPlayingPitch);
    checkPlayingSeUpdateAddition(i_sound, trackInfo, para->field_0x430, para->mFxmixes, 5, &trackUpdate->mPlayingFxmix, 0.0f);
    checkPlayingSeUpdateAddition(
        i_sound,
        trackInfo,
        para->field_0x438,
        para->mDolbys,
        6,
        &trackUpdate->mPlayingDolby,
        JAIGlobalParameter::getParamSeDolbyCenterValue() / 127.0f
    );
    if (trackInfo->trackupdate[i_sound->getPlayTrackNo()] != 0) {
        SystemInterface::setSeqPortargsU32(SequenceMgr::getPlayTrackInfo(seHandle->getPlayTrackNo()), i_sound->getPlayTrackNo(), 1, trackInfo->trackupdate[i_sound->getPlayTrackNo()]);
        trackInfo->systemTrackParameter[i_sound->getPlayTrackNo()].mCommand.addPortCmdOnce();
    }
}

